function makePath(seed,i){
 const [name,icon,desc,groups,beg,mid,adv,projectText,resText,prereq]=seed;
 const g=groups.split("|"), b=beg.split("|"),m=mid.split("|"),a=adv.split("|");
 return {id:"p"+i,name,icon,desc,prereq:prereq.split(",").map(x=>x.trim()),levels:[
  {name:"Beginner",topics:g.map((t,j)=>({id:`p${i}b${j}`,title:t,detail:b[j],hours:2+((j+i)%3),objectives:["Explain the core concepts in your own words","Complete a guided exercise and record evidence","Answer the knowledge check without relying on notes"]}))},
  {name:"Intermediate",topics:g.map((t,j)=>({id:`p${i}m${j}`,title:t,detail:m[j],hours:3+((j+i)%3),objectives:["Apply the concept to a realistic scenario","Compare at least two approaches or tools","Document a finding, decision or practical result"]}))},
  {name:"Advanced",topics:g.map((t,j)=>({id:`p${i}a${j}`,title:t,detail:a[j],hours:4+((j+i)%3),objectives:["Design or evaluate a complete workflow","Explain limitations, trade-offs and risks","Produce a portfolio-quality deliverable"]}))}
 ],project:projectText.split("|"),resourceText:resText};
}
const paths=pathSeeds.map(makePath);
