const projects = paths.map((p,i)=>{const t=projectTemplates[i%projectTemplates.length];return {id:"pr"+i,pathId:p.id,title:i===3?"Wazuh & Suricata Monitoring Lab":i===7?"Secure Web Application Review":t[0]+" — "+p.name,difficulty:t[1],objective:i===3?"Build an isolated defensive monitoring lab with Wazuh and Suricata, then document how telemetry supports investigation.":t[2],tools:i===3?"Kali Linux, Ubuntu VM, Wazuh, Suricata, VirtualBox":t[3],steps:i===3?["Draw the isolated lab architecture and define VM roles","Confirm host-only or otherwise restricted lab networking","Install and verify the monitoring components using official documentation","Generate benign test events inside the lab","Review alerts, timestamps and supporting logs","Write findings, limitations and remediation recommendations"]:t[4].split(", ").length>1?t[4].split(", "):[t[4]],deliverables:i===3?"Architecture diagram, configuration notes, alert evidence, investigation report and lessons learned":t[5],checks:["I understand the objective and prerequisites","I confirmed the environment is authorized and safely isolated","I completed the practical work and captured evidence","I explained the result and limitations","I documented remediation or next steps","I added a README and learning reflection"],repo:"README.md · docs/ · evidence/ (sanitized) · notes/ · screenshots/ (no secrets)",status:"Not started",evidence:"",github:""};});
