const defaultState={version:1,theme:"dark",completed:{},savedResources:[],projectState:{},skills:{},journal:[],tasks:[],activity:[],goals:[],quizAnswers:{},lastUpdated:new Date().toISOString()};
let state=loadState(), currentView="dashboard", activePath=null;
function loadState(){try{return {...defaultState,...JSON.parse(localStorage.getItem("cyberhub-state")||"{}")}}catch(e){return {...defaultState}}}
function save(){state.lastUpdated=new Date().toISOString();localStorage.setItem("cyberhub-state",JSON.stringify(state));}
function toast(msg){const el=$("#toast");el.textContent=msg;el.classList.add("show");setTimeout(()=>el.classList.remove("show"),2200)}
function logActivity(text){state.activity.unshift({text,date:new Date().toISOString()});state.activity=state.activity.slice(0,12);save()}
function allTopics(){return paths.flatMap(p=>p.levels.flatMap(l=>l.topics.map(t=>({...t,path:p.name,level:l.name,pathId:p.id}))));}
function topicDone(id){return !!state.completed[id]}
function totals(){const ts=allTopics();const done=ts.filter(t=>topicDone(t.id)).length;const ps=projects.filter(p=>(state.projectState[p.id]?.checks||[]).length===p.checks.length).length;return {topics:ts.length,done,percent:Math.round(done/ts.length*100),projects:projects.length,projectsDone:ps,skills:Object.values(state.skills).filter(x=>x==="Competent").length}}
function pathProgress(p){const ts=p.levels.flatMap(l=>l.topics);return {done:ts.filter(t=>topicDone(t.id)).length,total:ts.length,percent:Math.round(ts.filter(t=>topicDone(t.id)).length/ts.length*100)}}
function setView(view){currentView=view;activePath=null;render();$("#sidebar").classList.remove("open");}
function header(title,sub,eyebrow="YOUR LEARNING SPACE"){return `<div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="page-sub">${sub}</p>`}
function stat(label,value,note,icon){return `<div class="card"><div class="row"><span class="stat-label">${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function progress(pct){return `<div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div>`}
function renderDashboard(){const t=totals(), active=paths.filter(p=>pathProgress(p).done>0&&pathProgress(p).percent<100).slice(0,3), recent=state.activity.slice(0,5);return `${header("Your cybersecurity journey","A clear view of what you're learning, what you've built and what comes next.")}<div class="grid stats">${stat("Topics completed",`${t.done}/${t.topics}`,`${t.percent}% of curriculum complete`,"✓")}${stat("Projects completed",t.projectsDone,`Across ${t.projects} portfolio projects`,"▣")}${stat("Skills marked competent",t.skills,"Self-assessed skills","◈")}${stat("Journal entries",state.journal.length,"Learning reflections saved","✎")}</div><div class="notice"><strong>Suggested next move:</strong> Continue strengthening foundations, then build evidence through your Wazuh monitoring lab and a structured SOC investigation. Completion checkboxes track your progress; they do not certify professional competence.</div><div class="section-head"><div><h2>Explore your roadmaps</h2><p>15 connected learning paths · three levels each</p></div><button class="link-btn" data-go="roadmaps">View all →</button></div><div class="grid path-grid">${paths.slice(0,6).map(pathCard).join("")}</div><div class="grid two-col"><div><div class="section-head"><div><h2>Active learning paths</h2><p>Roadmaps where you've started checking off topics</p></div></div><div class="card">${active.length?active.map(p=>{let pr=pathProgress(p);return `<div class="activity"><div class="activity-dot"></div><div class="grow"><b>${esc(p.name)}</b><small>${pr.done} of ${pr.total} topics complete</small>${progress(pr.percent)}</div><span class="pill">${pr.percent}%</span></div>`}).join(""):`<div class="empty">No active paths yet. Open a roadmap and mark your first topic complete.</div>`}</div></div><div><div class="section-head"><div><h2>Recent activity</h2><p>Your latest learning actions</p></div></div><div class="card">${recent.length?recent.map(a=>`<div class="activity"><div class="activity-dot"></div><div><b>${esc(a.text)}</b><small>${fmtDate(a.date)}</small></div></div>`).join(""):`<div class="empty">Your activity will appear here as you learn.</div>`}</div></div></div>`}
function pathCard(p){const pr=pathProgress(p);return `<div class="card path-card" data-path="${p.id}"><div class="path-icon">${p.icon}</div><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p>${progress(pr.percent)}<div class="path-meta"><span>${pr.done}/${pr.total} topics</span><span>${pr.percent}%</span></div></div>`}
function renderRoadmaps(){if(activePath)return renderPathDetail(activePath);return `${header("Roadmap explorer","Choose a specialization or follow the recommended foundations-first sequence.")}<div class="notice"><strong>How to use:</strong> Open a path, expand each level and tick topics only after you can explain the concept and complete its practical exercise. Prerequisites are guidance, not hard locks.</div><div class="toolbar"><input class="input" id="pathSearch" placeholder="Search roadmaps..."><select class="select" id="pathFilter" style="max-width:180px"><option value="all">All progress</option><option value="started">Started</option><option value="not">Not started</option><option value="done">Completed</option></select></div><div class="grid path-grid" id="pathGrid">${paths.map(pathCard).join("")}</div>`}
function renderPathDetail(id){const p=paths.find(x=>x.id===id);if(!p)return "";const pr=pathProgress(p);return `<button class="link-btn" data-back-roadmaps>← All roadmaps</button>${header(p.name,p.desc,"LEARNING PATH")}<div class="grid two-col"><div class="card"><div class="row between"><div><span class="stat-label">PATH COMPLETION</span><div class="stat-value">${pr.percent}%</div></div><span class="pill purple">${pr.done}/${pr.total} topics</span></div>${progress(pr.percent)}<p class="stat-note">Estimated total: ${p.levels.flatMap(l=>l.topics).reduce((a,t)=>a+t.hours,0)} study hours (planning estimate).</p></div><div class="card"><span class="stat-label">PREREQUISITES</span><p style="font-size:11px;margin-bottom:0">${p.prereq.map(x=>`<span class="pill">${esc(x)}</span>`).join(" ")||"No formal prerequisites"}</p><p class="stat-note">Review prerequisites before starting advanced modules.</p></div></div>${p.levels.map((l,li)=>{let done=l.topics.filter(t=>topicDone(t.id)).length;return `<div class="level-block"><div class="level-title"><h3>${["01","02","03"][li]} · ${l.name}</h3><span class="pill">${done}/${l.topics.length} complete</span></div><div class="card">${l.topics.map(t=>`<label class="topic"><input type="checkbox" data-topic="${t.id}" ${topicDone(t.id)?"checked":""}><span class="topic-main"><b>${esc(t.title)}</b><p>${esc(t.detail)}</p><small>~${t.hours} hours · Learning outcomes: ${t.objectives.map(esc).join("; ")}</small></span><button class="link-btn" data-topic-info="${t.id}">Details</button></label>`).join("")}</div></div>`}).join("")}<div class="section-head"><div><h2>Suggested portfolio projects</h2><p>Use these to turn knowledge into demonstrable work</p></div><button class="link-btn" data-go="projects">Project lab →</button></div><div class="card"><ul>${p.project.map(x=>`<li style="font-size:11px;margin:7px 0">${esc(x)}</li>`).join("")}</ul><p class="stat-note">Recommended resources: ${esc(p.resourceText)}. See the Resource Library for verified links.</p></div>`}
const quizQuestions=[
 {q:"Which statement best describes the CIA triad?",a:["Confidentiality, Integrity and Availability","Control, Inspection and Authorization","Connectivity, Identity and Access","Classification, Investigation and Auditing"],correct:0,why:"The CIA triad describes protecting information confidentiality, preserving integrity and ensuring availability."},
 {q:"What does DNS primarily do?",a:["Encrypts all network traffic","Resolves domain names to records such as IP addresses","Assigns MAC addresses","Blocks malicious packets"],correct:1,why:"DNS provides a naming system and records used to locate services, including mapping names to IP addresses."},
 {q:"What is the main purpose of a SIEM platform?",a:["Replace every endpoint security tool","Aggregate and correlate security telemetry to support monitoring and investigation","Guarantee that incidents cannot occur","Create network cables"],correct:1,why:"A SIEM collects and analyzes logs and events to support detection, investigation and reporting."},
 {q:"In incident response, why preserve evidence integrity?",a:["To make files smaller","To ensure evidence remains trustworthy and changes can be detected","To avoid writing a report","To disable logging"],correct:1,why:"Integrity controls such as hashes and chain-of-custody records help demonstrate that evidence has not been altered."},
 {q:"What is the safest place to practise web vulnerability testing?",a:["A random public website","A colleague's account without asking","An intentionally vulnerable training lab or system you are authorized to test","A production payment system"],correct:2,why:"Practice only in intentionally vulnerable labs or systems for which you have explicit authorization."},
 {q:"What is least privilege?",a:["Give everyone administrator rights","Grant only the access needed to perform assigned tasks","Disable all user accounts","Use one shared account"],correct:1,why:"Least privilege limits access rights to what a person or service needs, reducing the impact of misuse or compromise."},
 {q:"What does MITRE ATT&CK organize?",a:["Adversary tactics and techniques based on observed behaviour","A list of antivirus product prices","Programming language syntax","A universal severity score"],correct:0,why:"ATT&CK is a knowledge base of adversary tactics, techniques and procedures across platforms and contexts."},
 {q:"What is a useful first step when triaging an alert?",a:["Assume it is malicious","Delete the alert","Validate context, source telemetry, scope and severity","Immediately shut down every system"],correct:2,why:"Triage begins with validating the alert and gathering context before deciding on escalation or containment."}
];
function renderAssessment(){const saved=state.quizAnswers||{};return `${header("Knowledge check","A short baseline quiz to help identify concepts to revisit. This is formative practice, not an exam or certification.","SELF-ASSESSMENT")}<div class="notice"><strong>How to use:</strong> Answer without notes first. Review the explanations afterward, then revisit the related roadmap topics. Your score is saved locally when you submit.</div><form id="quizForm"><div class="card">${quizQuestions.map((q,i)=>`<div style="padding:13px 0;border-bottom:1px solid var(--line)"><b style="font-size:11px">${i+1}. ${esc(q.q)}</b>${q.a.map((a,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}" ${saved.answers?.[i]===j?"checked":""}>${esc(a)}</label>`).join("")}${saved.submitted?`<p style="font-size:10px;color:${saved.answers?.[i]===q.correct?"var(--good)":"var(--warn)"}">${saved.answers?.[i]===q.correct?"Correct. ":"Review this one. "}${esc(q.why)}</p>`:""}</div>`).join("")}<div class="row between wrap" style="padding-top:15px"><span class="stat-note">${saved.submitted?`Last score: ${saved.score}/${quizQuestions.length} · ${Math.round(saved.score/quizQuestions.length*100)}%`:`${quizQuestions.length} questions · Choose one answer per question`}</span><button class="btn primary">${saved.submitted?"Retake knowledge check":"Submit answers"}</button></div></div></form>`}
function renderProjects(){return `${header("Project laboratory","Practical work turns theory into evidence. Keep all testing inside authorized, isolated environments.")}<div class="notice"><strong>Safety rule:</strong> Only test systems you own or have explicit permission to assess. Use intentionally vulnerable training labs, isolated virtual networks and non-sensitive sample data. Never publish credentials, tokens, personal data or unredacted logs.</div>${projects.map(p=>{const ps=state.projectState[p.id]||{checks:[],status:"Not started",evidence:"",github:""};const count=ps.checks.length;return `<div class="card project-card"><div class="row between wrap"><div><span class="pill ${p.difficulty==="Advanced"?"amber":p.difficulty==="Intermediate"?"purple":"green"}">${p.difficulty}</span> <span class="pill">${esc(paths.find(x=>x.id===p.pathId)?.name||"Core")}</span><h3 style="margin-top:9px">${esc(p.title)}</h3></div><select class="select project-status" data-project-status="${p.id}" style="max-width:145px"><option ${ps.status==="Not started"?"selected":""}>Not started</option><option ${ps.status==="In progress"?"selected":""}>In progress</option><option ${ps.status==="Completed"?"selected":""}>Completed</option></select></div><p>${esc(p.objective)}</p><div class="tag-list"><span class="pill">Tools: ${esc(p.tools)}</span></div><details><summary style="font-size:10px;color:var(--accent2);cursor:pointer">Open project brief & checklist (${count}/${p.checks.length})</summary><p style="font-size:10px"><b>Suggested steps</b></p><ol>${p.steps.map(s=>`<li style="font-size:10px;margin:5px 0">${esc(s)}</li>`).join("")}</ol><p style="font-size:10px"><b>Expected deliverables</b><br>${esc(p.deliverables)}</p><p style="font-size:10px"><b>Suggested repository structure</b><br><code>${esc(p.repo)}</code></p>${p.checks.map((c,i)=>`<label class="checkline"><input type="checkbox" data-project-check="${p.id}" data-check-index="${i}" ${(ps.checks||[]).includes(i)?"checked":""}>${esc(c)}</label>`).join("")}<div class="form-grid" style="margin-top:13px"><div class="field"><label>Evidence / notes link</label><input class="input project-evidence" data-project-evidence="${p.id}" value="${esc(ps.evidence||"")}" placeholder="https://... or short note"></div><div class="field"><label>GitHub repository</label><input class="input project-github" data-project-github="${p.id}" value="${esc(ps.github||"")}" placeholder="https://github.com/..."></div></div></details></div>`}).join("")}`}
function renderResources(){return `${header("Resource library","A curated starting shelf of official frameworks, documentation and practical learning platforms.")}<div class="toolbar"><input class="input" id="resourceSearch" placeholder="Search resources..."><select class="select" id="resourceCategory" style="max-width:200px"><option value="all">All categories</option>${[...new Set(resources.map(r=>r.category))].map(c=>`<option>${esc(c)}</option>`).join("")}</select><button class="btn ghost" id="savedOnly">☆ Saved only</button></div><div class="card" id="resourceList">${resourceRows(resources)}</div><div class="notice">Resource availability, course access, exam fees and certification objectives can change. Check the provider's official page before enrolling or paying. Last curated review: 6 November 2026.</div>`}
function resourceRows(items){return items.map(r=>`<div class="resource-row"><div class="path-icon" style="margin:0;width:32px;height:32px;font-size:13px">↗</div><div class="grow"><b>${esc(r.name)}</b><small>${esc(r.category)} · ${esc(r.type)}</small><div style="font-size:10px;color:var(--muted);margin-top:3px">${esc(r.desc)}</div><a href="${r.url}" target="_blank" rel="noopener noreferrer">Open official resource ↗</a></div><button class="icon-btn save-resource" data-save-resource="${r.id}" title="Save resource">${state.savedResources.includes(r.id)?"★":"☆"}</button></div>`).join("")||`<div class="empty">No matching resources.</div>`}
function renderSkills(){const groups=[...new Set(skills.map(s=>s.category))];return `${header("Skills tracker","Self-assess honestly. A skill becomes competent when you can apply it independently and explain your decisions.")}<div class="notice">Suggested evidence: a lab result, a written explanation, a code sample, a troubleshooting record or a reviewed project. Status is self-reported, not a formal certification.</div><div class="card">${groups.map(g=>`<div class="section-head"><h2>${esc(g)}</h2><span class="pill">${skills.filter(s=>s.category===g).length} skills</span></div>${skills.filter(s=>s.category===g).map(s=>`<div class="skill-row"><div class="grow"><b>${esc(s.name)}</b><small>${esc(s.category)}</small></div><select class="select skill-select" data-skill="${s.id}">${["Not started","Learning","Practicing","Competent","Needs revision"].map(v=>`<option ${((state.skills[s.id]||s.status)===v)?"selected":""}>${v}</option>`).join("")}</select></div>`).join("")}`).join("")}</div>`}
function renderPlanner(){const tasks=state.tasks;return `${header("Study planner","Set realistic learning targets and check them off as you complete them.")}<div class="card"><h2 style="font-size:14px;margin-top:0">Add a study task</h2><form id="taskForm" class="form-grid"><div class="field"><label>Task</label><input class="input" name="title" required placeholder="e.g. Review DNS and complete notes"></div><div class="field"><label>Target date</label><input class="input" type="date" name="date"></div><div class="field"><label>Estimated minutes</label><input class="input" type="number" name="minutes" min="5" step="5" value="45"></div><div class="field"><label>Priority</label><select class="select" name="priority"><option>Normal</option><option>High</option><option>Low</option></select></div><div class="field full"><button class="btn primary">Add to planner</button></div></form></div><div class="section-head"><div><h2>Your tasks</h2><p>${tasks.filter(t=>!t.done).length} remaining · ${tasks.filter(t=>t.done).length} completed</p></div></div><div class="card">${tasks.length?tasks.sort((a,b)=>(a.date||"9999").localeCompare(b.date||"9999")).map(t=>`<div class="topic"><input type="checkbox" data-task="${t.id}" ${t.done?"checked":""}><div class="topic-main"><b style="${t.done?"text-decoration:line-through;color:var(--muted)":""}">${esc(t.title)}</b><p>${t.date?fmtDate(t.date):"No due date"} · ${t.minutes} min · ${esc(t.priority)} priority</p></div><button class="link-btn" data-delete-task="${t.id}">Delete</button></div>`).join(""):`<div class="empty">No tasks yet. Add a small, specific learning target above.</div>`}</div>`}
function renderJournal(){return `${header("Learning journal","Capture what you learned, what challenged you and what you want to investigate next.")}<div class="card"><h2 style="font-size:14px;margin-top:0">New journal entry</h2><form id="journalForm" class="form-grid"><div class="field"><label>Entry title</label><input class="input" name="title" required placeholder="What did you work on?"></div><div class="field"><label>Related area</label><select class="select" name="area">${paths.map(p=>`<option>${esc(p.name)}</option>`).join("")}</select></div><div class="field full"><label>What I learned</label><textarea class="textarea" name="learned" placeholder="Concepts, commands, observations..."></textarea></div><div class="field"><label>Challenge encountered</label><textarea class="textarea" name="challenge" placeholder="What was difficult?"></textarea></div><div class="field"><label>How I solved it / next question</label><textarea class="textarea" name="solution" placeholder="Steps, references, next actions..."></textarea></div><div class="field full"><button class="btn primary">Save journal entry</button></div></form></div><div class="section-head"><h2>Previous entries</h2><span class="pill">${state.journal.length} saved</span></div>${state.journal.length?state.journal.slice().reverse().map(j=>`<div class="card journal-entry"><div class="row between"><span class="pill">${esc(j.area)}</span><small class="stat-note">${fmtDate(j.date)}</small></div><h3>${esc(j.title)}</h3><p><b>Learned:</b> ${esc(j.learned||"—")}</p><p><b>Challenge:</b> ${esc(j.challenge||"—")}</p><p><b>Resolution / next step:</b> ${esc(j.solution||"—")}</p><button class="link-btn" data-delete-journal="${j.id}">Delete entry</button></div>`).join(""):`<div class="card empty">Your learning reflections will appear here.</div>`}`}
function renderCareer(){return `${header("Career & certifications","Use certifications to structure learning, not as a substitute for practical skills and portfolio evidence.")}<div class="notice"><strong>Before paying for an exam:</strong> Confirm the active exam code, official objectives, prerequisites, renewal policy, exam delivery options and current price on the issuer's website. Pricing and availability vary by country.</div><div class="section-head"><h2>Certification shortlist</h2></div>${certs.map(c=>`<div class="card cert-card"><div class="row between"><h3>${esc(c.name)}</h3><span class="pill purple">${esc(c.path)}</span></div><p>${esc(c.note)}</p><a href="${c.url}" target="_blank" rel="noopener noreferrer" style="color:var(--accent2);font-size:10px;text-decoration:none">Official certification information ↗</a></div>`).join("")}<div class="section-head"><h2>Portfolio readiness checklist</h2></div><div class="card">${["A clear GitHub profile and professional README","At least three well-documented projects across different skill areas","Sanitized evidence, diagrams and repeatable steps","Project write-ups explain objective, approach, findings and remediation","No secrets, credentials, personal data or unauthorized targets in repositories","A concise CV that describes demonstrable skills honestly","A short explanation of one project that I can present in an interview"].map((x,i)=>`<label class="checkline"><input type="checkbox" data-career-check="${i}" ${state.completed["career"+i]?"checked":""}>${esc(x)}</label>`).join("")}</div>`}
function renderProgress(){const t=totals();return `${header("Progress & achievements","A snapshot of your learning activity and the evidence you've recorded.")}<div class="grid stats">${stat("Curriculum completion",t.percent+"%","Across all roadmap topics","◷")}${stat("Topics completed",t.done,"Of "+t.topics+" available topics","✓")}${stat("Projects fully checked",t.projectsDone,"Of "+t.projects+" project briefs","▣")}${stat("Competent skills",t.skills,"Self-assessed","◈")}</div><div class="grid two-col"><div class="card"><h2 style="font-size:14px;margin-top:0">Roadmap progress</h2>${paths.map(p=>{let pr=pathProgress(p);return `<div class="bar-row"><span>${esc(p.name)}</span>${progress(pr.percent)}<b>${pr.percent}%</b></div>`}).join("")}</div><div class="card"><h2 style="font-size:14px;margin-top:0">Milestones</h2><div class="badge-row">${t.done>=1?'<span class="badge">✓ First topic completed</span>':""}${t.done>=10?'<span class="badge">✦ 10 topics completed</span>':""}${t.projectsDone>=1?'<span class="badge">▣ First project checklist complete</span>':""}${state.journal.length>=1?'<span class="badge">✎ First reflection saved</span>':""}${t.skills>=5?'<span class="badge">◈ 5 skills marked competent</span>':""}${t.done===0&&t.projectsDone===0?'<span class="stat-note">Complete your first topic or project to unlock a milestone.</span>':""}</div><div class="section-head"><h2>Learning activity</h2></div>${state.activity.length?state.activity.map(a=>`<div class="activity"><div class="activity-dot"></div><div><b>${esc(a.text)}</b><small>${fmtDate(a.date)}</small></div></div>`).join(""):'<div class="empty">No activity recorded yet.</div>'}</div></div><div class="section-head"><h2>Exportable summary</h2><button class="btn primary" id="downloadReport">Download progress report</button></div>`}
function renderSettings(){return `${header("Settings & backup","Your progress is stored locally in this browser on this device. Back it up regularly.")}<div class="grid two-col"><div class="card"><h2 style="font-size:14px;margin-top:0">Data backup</h2><p class="stat-note">Export creates a JSON backup containing progress, journal entries, tasks, saved resources and skill statuses. Keep it somewhere private.</p><div class="row wrap"><button class="btn primary" id="exportData">Export backup</button><label class="btn ghost" for="importFile">Import backup</label><input id="importFile" type="file" accept="application/json" hidden></div><p class="stat-note" style="margin-top:15px">Last saved: ${fmtDate(state.lastUpdated)}</p></div><div class="card"><h2 style="font-size:14px;margin-top:0">Appearance</h2><p class="stat-note">Choose a comfortable display theme.</p><button class="btn" id="themeSettings">${state.theme==="light"?"Switch to dark mode":"Switch to light mode"}</button></div></div><div class="card" style="margin-top:15px"><h2 style="font-size:14px;margin-top:0">Curriculum maintenance</h2><p class="stat-note">Roadmap version 1.0 · Reviewed 6 November 2026 · This is a curated snapshot, not a live feed. External providers may change content without notice.</p><ul style="font-size:10px;color:var(--muted);padding-left:18px"><li>Check official framework pages every 3–6 months.</li><li>Recheck certification exam codes and objectives before planning an exam.</li><li>Review lab platform paths before starting; retired paths should not be treated as current.</li><li>Record a new review date and changelog entry when updating content.</li></ul><div class="notice"><strong>Current reference notes:</strong> NIST CSF 2.0; NICE Framework Components v2.2.0; MITRE ATT&CK v20.0; OWASP Top 10:2025; CIS Controls v8.1. Verify each on its official site during each review.</div></div><div class="card" style="margin-top:15px"><h2 style="font-size:14px;margin-top:0">Reset local workspace</h2><p class="stat-note">This permanently clears progress from this browser. Export a backup first.</p><button class="btn danger" id="resetData">Reset all local data</button></div>`}
function render(){const map={dashboard:renderDashboard,roadmaps:renderRoadmaps,assessment:renderAssessment,projects:renderProjects,resources:renderResources,skills:renderSkills,planner:renderPlanner,journal:renderJournal,career:renderCareer,progress:renderProgress,settings:renderSettings};const titles={dashboard:"Dashboard",roadmaps:"Roadmap explorer",assessment:"Knowledge check",projects:"Project laboratory",resources:"Resource library",skills:"Skills tracker",planner:"Study planner",journal:"Learning journal",career:"Career & certifications",progress:"Progress & achievements",settings:"Settings & backup"};$("#pageName").textContent=activePath&&currentView==="roadmaps"?"Roadmap detail":titles[currentView];$("#content").innerHTML=map[currentView]();$$(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.view===currentView));bindViewEvents();$("#todayLabel").textContent=fmtDate(today);}
function openModal(title,html){$("#modalTitle").textContent=title;$("#modalBody").innerHTML=html;$("#modal").showModal()}
function bindViewEvents(){
 $$("[data-go]").forEach(b=>b.addEventListener("click",()=>setView(b.dataset.go)));
 $$("[data-path]").forEach(el=>el.addEventListener("click",()=>{activePath=el.dataset.path;render()}));
 $$("[data-back-roadmaps]").forEach(b=>b.addEventListener("click",()=>{activePath=null;render()}));
 $$("[data-topic]").forEach(c=>c.addEventListener("change",()=>{state.completed[c.dataset.topic]=c.checked;logActivity((c.checked?"Completed: ":"Reopened: ")+allTopics().find(t=>t.id===c.dataset.topic).title);render()}));
 $$("[data-topic-info]").forEach(b=>b.addEventListener("click",()=>{const t=allTopics().find(x=>x.id===b.dataset.topicInfo);openModal(t.title,`<p style="font-size:11px;color:var(--muted)">${esc(t.detail)}</p><h4 style="font-size:11px">Learning outcomes</h4><ul>${t.objectives.map(x=>`<li style="font-size:10px;margin:6px 0">${esc(x)}</li>`).join("")}</ul><p class="stat-note">Suggested method: study the concept, practise it in an authorized lab, write a short explanation and test yourself without notes.</p>`)}));
 const ps=$("#pathSearch"),pf=$("#pathFilter");if(ps)ps.addEventListener("input",filterPaths);if(pf)pf.addEventListener("change",filterPaths);
 $$("[data-save-resource]").forEach(b=>b.addEventListener("click",()=>{const id=b.dataset.saveResource;state.savedResources=state.savedResources.includes(id)?state.savedResources.filter(x=>x!==id):[...state.savedResources,id];save();render()}));
 const rs=$("#resourceSearch"),rc=$("#resourceCategory"),so=$("#savedOnly");if(rs)rs.addEventListener("input",filterResources);if(rc)rc.addEventListener("change",filterResources);if(so)so.addEventListener("click",()=>{so.classList.toggle("primary");so.dataset.only=so.dataset.only==="1"?"0":"1";filterResources()});
 $$("[data-skill]").forEach(s=>s.addEventListener("change",()=>{state.skills[s.dataset.skill]=s.value;save();logActivity("Updated skill status: "+skills.find(x=>x.id===s.dataset.skill).name);}));
 $$("[data-project-status]").forEach(s=>s.addEventListener("change",()=>{const p=state.projectState[s.dataset.projectStatus]||{checks:[]};p.status=s.value;state.projectState[s.dataset.projectStatus]=p;save();logActivity("Project status updated: "+projects.find(x=>x.id===s.dataset.projectStatus).title)}));
 $$("[data-project-check]").forEach(c=>c.addEventListener("change",()=>{const id=c.dataset.projectCheck,idx=+c.dataset.checkIndex,p=state.projectState[id]||{checks:[],status:"In progress"};p.checks=p.checks||[];p.checks=c.checked?[...new Set([...p.checks,idx])]:p.checks.filter(x=>x!==idx);if(p.checks.length===projects.find(x=>x.id===id).checks.length)p.status="Completed";else if(p.checks.length)p.status="In progress";state.projectState[id]=p;save();logActivity("Updated project checklist: "+projects.find(x=>x.id===id).title);render()}));
 $$("[data-project-evidence]").forEach(i=>i.addEventListener("change",()=>{let p=state.projectState[i.dataset.projectEvidence]||{checks:[]};p.evidence=i.value;state.projectState[i.dataset.projectEvidence]=p;save()}));
 $$("[data-project-github]").forEach(i=>i.addEventListener("change",()=>{let p=state.projectState[i.dataset.projectGithub]||{checks:[]};p.github=i.value;state.projectState[i.dataset.projectGithub]=p;save()}));
 const qf=$("#quizForm");if(qf)qf.addEventListener("submit",e=>{e.preventDefault();const fd=new FormData(qf),answers=quizQuestions.map((q,i)=>fd.has("q"+i)?+fd.get("q"+i):null);if(answers.some(x=>x===null)){toast("Please answer every question first");return}const score=answers.reduce((n,a,i)=>n+(a===quizQuestions[i].correct?1:0),0);state.quizAnswers={answers,score,submitted:true,date:new Date().toISOString()};save();logActivity("Completed knowledge check: "+score+"/"+quizQuestions.length);render()});
 const tf=$("#taskForm");if(tf)tf.addEventListener("submit",e=>{e.preventDefault();const f=new FormData(tf);state.tasks.push({id:uid(),title:f.get("title"),date:f.get("date"),minutes:+f.get("minutes"),priority:f.get("priority"),done:false});save();logActivity("Added study task: "+f.get("title"));render()});
 $$("[data-task]").forEach(c=>c.addEventListener("change",()=>{let t=state.tasks.find(x=>x.id===c.dataset.task);t.done=c.checked;save();logActivity((t.done?"Completed":"Reopened")+" study task: "+t.title);render()}));
 $$("[data-delete-task]").forEach(b=>b.addEventListener("click",()=>{state.tasks=state.tasks.filter(t=>t.id!==b.dataset.deleteTask);save();render()}));
 const jf=$("#journalForm");if(jf)jf.addEventListener("submit",e=>{e.preventDefault();const f=new FormData(jf);state.journal.push({id:uid(),title:f.get("title"),area:f.get("area"),learned:f.get("learned"),challenge:f.get("challenge"),solution:f.get("solution"),date:new Date().toISOString()});save();logActivity("Saved journal entry: "+f.get("title"));render()});
 $$("[data-delete-journal]").forEach(b=>b.addEventListener("click",()=>{state.journal=state.journal.filter(j=>j.id!==b.dataset.deleteJournal);save();render()}));
 $$("[data-career-check]").forEach(c=>c.addEventListener("change",()=>{state.completed["career"+c.dataset.careerCheck]=c.checked;save()}));
 const exp=$("#exportData");if(exp)exp.addEventListener("click",exportBackup);const imp=$("#importFile");if(imp)imp.addEventListener("change",importBackup);
 const th=$("#themeSettings");if(th)th.addEventListener("click",toggleTheme);const reset=$("#resetData");if(reset)reset.addEventListener("click",()=>{if(confirm("Clear all CyberHub data from this browser? Export a backup first.")){localStorage.removeItem("cyberhub-state");state=loadState();toast("Local data reset");render()}});
 const rep=$("#downloadReport");if(rep)rep.addEventListener("click",downloadReport);
}
function filterPaths(){const q=($("#pathSearch")?.value||"").toLowerCase(),f=$("#pathFilter")?.value||"all";const arr=paths.filter(p=>{const pr=pathProgress(p);return (p.name+" "+p.desc).toLowerCase().includes(q)&&(f==="all"||(f==="started"&&pr.done>0&&pr.percent<100)||(f==="not"&&pr.done===0)||(f==="done"&&pr.percent===100))});$("#pathGrid").innerHTML=arr.map(pathCard).join("");$$("[data-path]").forEach(el=>el.addEventListener("click",()=>{activePath=el.dataset.path;render()}))}
function filterResources(){const q=($("#resourceSearch")?.value||"").toLowerCase(),cat=$("#resourceCategory")?.value||"all",only=$("#savedOnly")?.dataset.only==="1";const arr=resources.filter(r=>(r.name+" "+r.desc+" "+r.category).toLowerCase().includes(q)&&(cat==="all"||r.category===cat)&&(!only||state.savedResources.includes(r.id)));$("#resourceList").innerHTML=resourceRows(arr);$$("[data-save-resource]").forEach(b=>b.addEventListener("click",()=>{const id=b.dataset.saveResource;state.savedResources=state.savedResources.includes(id)?state.savedResources.filter(x=>x!==id):[...state.savedResources,id];save();filterResources()}))}
function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:"application/json"});downloadBlob(blob,"cyberhub-backup-"+new Date().toISOString().slice(0,10)+".json");toast("Backup exported")}
function importBackup(e){const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!data||typeof data!=="object"||!data.completed)throw Error("Invalid backup");if(confirm("Replace current local data with this backup?")){state={...defaultState,...data};save();toast("Backup restored");render()}}catch(err){alert("Could not import this file. Please choose a CyberHub JSON backup.")}};reader.readAsText(file)}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function downloadReport(){const t=totals(),lines=["CYBERHUB LEARNING REPORT", "Generated: "+new Date().toLocaleString(),"",`Curriculum progress: ${t.done}/${t.topics} (${t.percent}%)`,`Projects fully checked: ${t.projectsDone}/${t.projects}`,`Journal entries: ${state.journal.length}`,"","ROADMAPS",...paths.map(p=>{const pr=pathProgress(p);return `${p.name}: ${pr.done}/${pr.total} (${pr.percent}%)`}),"","SKILLS",...skills.map(s=>`${s.name}: ${state.skills[s.id]||s.status}`),"","PROJECTS",...projects.map(p=>`${p.title}: ${(state.projectState[p.id]||{}).status||"Not started"}`)];downloadBlob(new Blob([lines.join("\n")],{type:"text/plain"}),"cyberhub-progress-report.txt")}
function toggleTheme(){state.theme=state.theme==="light"?"dark":"light";document.body.classList.toggle("light",state.theme==="light");save();if(currentView==="settings")render()}
$("#themeToggle").addEventListener("click",toggleTheme);$("#mobileMenu").addEventListener("click",()=>$("#sidebar").classList.toggle("open"));$("#modalClose").addEventListener("click",()=>$("#modal").close());
$$(".nav-item").forEach(b=>b.addEventListener("click",()=>setView(b.dataset.view)));
document.body.classList.toggle("light",state.theme==="light");
if("serviceWorker" in navigator && location.protocol!=="file:"){window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").catch(()=>{}))}
render();
